1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
10	
11	/**
12	 * Rejects creating an owner who shares both last name and address with an existing owner, so the
13	 * create endpoint responds 409 instead of storing a second member of the same household.
14	 * Last name and address are compared case-insensitively with runs of whitespace collapsed to a
15	 * single space. The check is skipped when the request opts in with {@code sharesHousehold: true}
16	 * (an intentionally shared household). Runs after {@link ValidateOwner} (which publishes the body)
17	 * and before {@link BuildOwner}, comparing against every existing owner.
18	 */
19	public class CheckHouseholdUnique {
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
22	            throws DuplicateHouseholdException {
23	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
24	            return;
25	        }
26	        String lastName = normalize(request.getLastName());
27	        String address = AddressNormalizer.normalize(request.getAddress());
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (lastName.equals(normalize(existing.getLastName()))
30	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
31	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
32	            }
33	        }
34	    }
35	
36	    /** Lower-cases and collapses whitespace so comparison ignores case and spacing differences. */
37	    private static String normalize(String value) {
38	        if (value == null) {
39	            return "";
40	        }
41	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
42	    }
43	}
