1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	
13	/**
14	 * Assigns a shared {@code householdId} when the request opts in with {@code sharesHousehold: true}.
15	 *
16	 * <p>The identifier is derived deterministically from the normalized last name and address (the same
17	 * fields {@link CheckHouseholdUnique} compares), so it is stable: every owner living at the same
18	 * address under the same last name gets the same value regardless of creation order. The new owner and
19	 * every existing owner in that household are stamped with it, so both sides of an intentionally shared
20	 * household report the identifier. When {@code sharesHousehold} is not true no identifier is assigned.
21	 *
22	 * <p>Runs after {@link BuildOwner} (which publishes the new owner) and before {@link SaveOwner}.
23	 */
24	public class AssignHousehold {
25	
26	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
27	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
28	            return;
29	        }
30	        String lastName = normalize(owner.getLastName());
31	        String address = AddressNormalizer.normalize(owner.getAddress());
32	        String householdId = householdId(lastName, address);
33	        owner.setHouseholdId(householdId);
34	        // Stamp existing members of the same household so both sides share the identifier.
35	        for (Owner existing : ownerRepository.findAll()) {
36	            if (lastName.equals(normalize(existing.getLastName()))
37	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))
38	                    && !householdId.equals(existing.getHouseholdId())) {
39	                existing.setHouseholdId(householdId);
40	                ownerRepository.save(existing);
41	            }
42	        }
43	    }
44	
45	    /** A stable, shared identifier: the first 16 upper-case hex chars of SHA-256(lastName|address). */
46	    private static String householdId(String lastName, String address) {
47	        try {
48	            byte[] digest = MessageDigest.getInstance("SHA-256")
49	                    .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
50	            StringBuilder sb = new StringBuilder(32);
51	            for (byte b : digest) {
52	                sb.append(String.format("%02x", b));
53	            }
54	            return sb.substring(0, 16).toUpperCase(Locale.ROOT);
55	        }
56	        catch (NoSuchAlgorithmException e) {
57	            throw new IllegalStateException("SHA-256 not available", e);
58	        }
59	    }
60	
61	    /** Lower-cases and collapses whitespace so comparison ignores case and spacing differences. */
62	    private static String normalize(String value) {
63	        if (value == null) {
64	            return "";
65	        }
66	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
67	    }
68	}
