3	import java.util.Locale;
4	import java.util.regex.Pattern;
5	
6	/**
7	 * Normalizes a street address to a canonical stored form.
8	 *
9	 * <p>Rules: trim the ends, collapse every run of whitespace to a single space, upper-case the
10	 * whole string, then expand common abbreviations as whole words: {@code ST -> STREET},
11	 * {@code RD -> ROAD}, {@code AVE -> AVENUE}. Expansion is token-based, so an abbreviation embedded
12	 * in a longer word (e.g. {@code STANMORE}) is left untouched. A {@code null} or all-whitespace
13	 * input yields the empty string, which the required-field check treats as a blank address.
14	 *
15	 * <p>Example: {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
16	 */
17	final class AddressNormalizer {
18	
19	    /** Any run of whitespace, collapsed to a single space. */
20	    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
21	
22	    private AddressNormalizer() {
23	    }
24	
25	    /** Convert to the canonical stored form; {@code null}/blank input yields {@code ""}. */
26	    static String normalize(String raw) {
27	        if (raw == null) {
28	            return "";
29	        }
30	        String collapsed = WHITESPACE.matcher(raw.trim()).replaceAll(" ").toUpperCase(Locale.ROOT);
31	        if (collapsed.isEmpty()) {
32	            return "";
33	        }
34	        String[] tokens = collapsed.split(" ");
35	        StringBuilder sb = new StringBuilder(collapsed.length());
36	        for (int i = 0; i < tokens.length; i++) {
37	            if (i > 0) {
38	                sb.append(' ');
39	            }
40	            sb.append(expand(tokens[i]));
41	        }
42	        return sb.toString();
43	    }
44	
45	    /** Expand a single whole-word abbreviation, or return the token unchanged. */
46	    private static String expand(String token) {
47	        switch (token) {
48	            case "ST":
49	                return "STREET";
50	            case "RD":
51	                return "ROAD";
52	            case "AVE":
53	                return "AVENUE";
54	            default:
55	                return token;
56	        }
57	    }
58	}
